  "id": "release-06-file-001-dow-uap-d102-project-blue-book-file-on-tremonton-film-utah-1952",
  "slug": "release-06-file-001-dow-uap-d102-project-blue-book-file-on-tremonton-film-utah-1952",
  "title": "DOW-UAP-D102, Project Blue Book File on Tremonton Film, Utah, 1952",
  "agency": "DOW",
