  "classification": "DECLASSIFIED",
  "summary": "This document records the Project Blue Book investigation and subsequent assessments of an incident near Tremonton, Utah, on July 2, 1952. Project Blue Book was a 1952-1969 U.S. Air Force program to investigate the nature and origin of unidentified flying objects (UFOs). The file describes the Air Force’s assessment of the principal witness, Delbert C. Newhouse, a U.S. Navy Warrant Officer specializing in photography, as honest and reliable, and as an expert with more than 1,000 hours of aerial-photography experience. Newhouse reported observing 12 to 14 reflective objects and recorded the event on color motion-picture film using a handheld Bell & Howell Auto Master camera. The file reflects an evolving Air Force assessment of the imagery over several years. Early documentation considered several possible explanations, including sunlight reflecting from birds or balloons, and a mirage effect, and did not identify the objects conclusively. Later assessments became more confident that the objects were seabirds reflecting sunlight, citing identifiable seabirds and similar films showing seabirds as bright points of light under comparable conditions. However, the film’s limited detail and lack of fixed reference points prevented reliable determination of the objects’ distance, size, altitude, or linear speed from the film alone. AARO Comment: The file contains conflicting references to the film format. Several documents describe a 35mm film, while contemporaneous submission documentation identifies the original as a 50-foot roll of processed 16mm Kodachrome color motion-picture film recorded with a handheld Bell & Howell Auto Master camera. Newhouse reported exposing approximately 30 feet of the roll during the incident and using the remaining film later that day to record unrelated mountain scenery in Idaho. Other records show that 35mm positive and negative duplicate blowups were produced from the original 16mm material. The file also indicates that the original film was duplicated for preservation, citing its deteriorating condition. The footage retained by the National Archives and Records Administration and presented in this collection as DOW-UAP-PR159 is a digitization of a 16mm print.",
  "keyFindings": [
    "The releasing office pairs this record with DOW-UAP-PR159, DOW-UAP-D098, DOW-UAP-D103, DOW-UAP-D104, DOW-UAP-D105.",
    "Official record metadata lists incident date 7/2/52 and location Tremonton, Utah.",
    "Released as part of PURSUE Release 06 on September 18, 2026."
  ],
