  "classification": "DECLASSIFIED",
  "summary": "This document is an administrative or programmatic record related to the Advanced Aerospace Weapon System Applications Program (AAWSAP), a Defense Intelligence Agency (DIA)-administered program active from 2008 to 2012. AAWSAP’s official scope of work identified 12 technical research areas relating to potential aerospace threats over a time horizon of more than 40 years. As an administrative record, the file documents how AAWSAP was scoped, organized, tasked, funded, or described at a particular point in time. This July 2008 Statement of Objectives defines AAWSAP as a contractor-supported research effort intended to assess far-term foreign aerospace threats by understanding the physics and engineering of possible breakthrough technologies out to the year 2050 rather than extrapolating from then-current aerospace trends. It identifies 12 technical study areas, including lift, propulsion, control, power generation, spatial or temporal translation, materials, configuration and structure, signature reduction, human interface, human effects, armament, and related supporting topics. The document also sets out the program’s expected work structure, requiring monthly status reports, technical-area program management plans within 60 days, comprehensive research reports and briefings by the tenth month, and a final integrated threat assessment.",
