  "summary": "This document is an administrative or programmatic record related to the Advanced Aerospace Weapon System Applications Program (AAWSAP), a Defense Intelligence Agency (DIA)-administered program active from 2008 to 2012. AAWSAP’s official scope of work identified 12 technical research areas relating to potential aerospace threats over a time horizon of more than 40 years. As an administrative record, the file documents how AAWSAP was scoped, organized, tasked, funded, or described at a particular point in time. This September 2010 contract modification extends the period of performance for the AAWSAP contract (HHM402-08-C-0072) from September 22, 2010, to December 21, 2010. The modification states that no additional funding was required for the extension and that no other changes were made to the contract. This bridge action extended AAWSAP contractor support beyond the previously established performance end date without changing the underlying scope of work.",
