  "id": "release-06-file-026-dow-uap-d121-aawsap-dird-pulsed-high-power-microwave-source-technology-january-2010",
  "slug": "release-06-file-026-dow-uap-d121-aawsap-dird-pulsed-high-power-microwave-source-technology-january-2010",
  "title": "DOW-UAP-D121, AAWSAP DIRD, Pulsed High-Power Microwave Source Technology, January 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-01-28",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
