  "id": "release-06-file-027-dow-uap-d122-aawsap-dird-invisibility-cloaking-theory-and-experiments-march-2010",
  "slug": "release-06-file-027-dow-uap-d122-aawsap-dird-invisibility-cloaking-theory-and-experiments-march-2010",
  "title": "DOW-UAP-D122, AAWSAP DIRD, Invisibility Cloaking Theory and Experiments, March 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-03-02",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
  "location": {
    "name": "Las Vegas, Nevada",
    "region": "North America",
    "lat": 36.17,
    "lng": -115.14
  },
  "classification": "DECLASSIFIED",
  "summary": "This document is a Defense Intelligence Reference Document (DIRD), a technical reference format used by the Defense Intelligence Agency (DIA) to capture baseline knowledge on a specific topic for later analytic use. DIRDs are best understood as reference and synthesis products rather than as original research. It is one of 38 DIRDs produced under the Advanced Aerospace Weapon System Applications Program (AAWSAP) between 2009 and 2011. Because AAWSAP’s scope permitted a broad range of supporting topics, not every DIRD in the series directly concerns aerospace systems or future threat assessment. The following summary reflects the DIRD’s scope and framing at the time of writing and should not be read as implying current validation of the concepts discussed. This DIRD surveys the theory and early experiments behind invisibility cloaking, describing several ways an object might be hidden from visual or sensor detection, including camouflage, transparency effects, and optical cloaking that bends light around an object. It focuses mainly on metamaterials, negative refraction, and transformation optics, and reviews experiments that had already demonstrated limited cloaking at microwave frequencies. The report argues that “imperfect” cloaking is physically achievable in some parts of the electromagnetic spectrum, especially for microwaves, but that “perfect” cloaking is not practical because it would require material properties that conflict with the underlying physics. Its overall conclusion is that cloaking is a scientific field with plausible narrow applications, but that useful visible-light cloaking depends more on future theoretical breakthroughs than on conventional advances in materials science.",
