  "classification": "DECLASSIFIED",
  "summary": "This document is a Defense Intelligence Reference Document (DIRD), a technical reference format used by the Defense Intelligence Agency (DIA) to capture baseline knowledge on a specific topic for later analytic use. DIRDs are best understood as reference and synthesis products rather than as original research. It is one of 38 DIRDs produced under the Advanced Aerospace Weapon System Applications Program (AAWSAP) between 2009 and 2011. Because AAWSAP’s scope permitted a broad range of supporting topics, not every DIRD in the series directly concerns aerospace systems or future threat assessment. The following summary reflects the DIRD’s scope and framing at the time of writing and should not be read as implying current validation of the concepts discussed. This DIRD examines positrons as a possible fuel for advanced aerospace propulsion, arguing that antimatter offers extraordinary energy density and could, in principle, support applications ranging from long-endurance aircraft and missiles to single-stage launch vehicles, onboard power systems, and crewed Mars missions. At the same time, it makes clear that the concept depends on resolving major unsolved problems in producing positrons in sufficient quantities and storing them safely for long periods, and much of the document’s discussion of flight systems and Mars missions remains conceptual rather than closely tied to demonstrated engineering practice. Its overall conclusion is that positron propulsion is theoretically attractive, but remains highly speculative as a practical technology because its core production and storage requirements remain unsolved.",
