  "id": "release-06-file-035-dow-uap-d131-aawsap-dird-the-role-of-superconductors-in-gravity-research-march-2010",
  "slug": "release-06-file-035-dow-uap-d131-aawsap-dird-the-role-of-superconductors-in-gravity-research-march-2010",
  "title": "DOW-UAP-D131, AAWSAP DIRD, The Role of Superconductors in Gravity Research, March 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-03-23",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
