  "slug": "release-06-file-039-dow-uap-d135-aawsap-dird-antigravity-for-aerospace-applications-march-2010",
  "title": "DOW-UAP-D135, AAWSAP DIRD, Antigravity for Aerospace Applications, March 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-03-30",
  "year": 2010,
  "dateReleased": "2026-09-18",
