  "id": "release-06-file-040-dow-uap-d136-aawsap-dird-biosensors-and-biomems-a-survey-of-the-present-field-march-2010",
  "slug": "release-06-file-040-dow-uap-d136-aawsap-dird-biosensors-and-biomems-a-survey-of-the-present-field-march-2010",
  "title": "DOW-UAP-D136, AAWSAP DIRD, Biosensors and BioMEMS: A Survey of the Present Field, March 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-03-31",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
