  "id": "release-06-file-042-dow-uap-d138-aawsap-dird-warp-drive-dark-energy-and-the-manipulation-of-extra-dimensions-april-2010",
  "slug": "release-06-file-042-dow-uap-d138-aawsap-dird-warp-drive-dark-energy-and-the-manipulation-of-extra-dimensions-april-2010",
  "title": "DOW-UAP-D138, AAWSAP DIRD, Warp Drive, Dark Energy, and the Manipulation of Extra Dimensions, April 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-04-02",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
  "location": {
    "name": "Las Vegas, Nevada",
    "region": "North America",
    "lat": 36.17,
    "lng": -115.14
  },
  "classification": "DECLASSIFIED",
  "summary": "This document is a Defense Intelligence Reference Document (DIRD), a technical reference format used by the Defense Intelligence Agency (DIA) to capture baseline knowledge on a specific topic for later analytic use. DIRDs are best understood as reference and synthesis products rather than as original research. It is one of 38 DIRDs produced under the Advanced Aerospace Weapon System Applications Program (AAWSAP) between 2009 and 2011. Because AAWSAP’s scope permitted a broad range of supporting topics, not every DIRD in the series directly concerns aerospace systems or future threat assessment. The following summary reflects the DIRD’s scope and framing at the time of writing and should not be read as implying current validation of the concepts discussed. This DIRD examines whether a warp-propulsion concept can be grounded in known theoretical physics by linking general-relativistic warp metrics with dark energy, Casimir effects, and higher-dimensional models from string theory and brane cosmology. The paper hypothesizes that if dark energy arises from vacuum effects and originates in extra dimensions, then a future technology capable of manipulating those dimensions might be capable of altering local spacetime expansion to generate a warp bubble. While framed as a method to mitigate the astronomical energy demands of more traditional warp models, the report acknowledges that this concept relies entirely on unverified assumptions; namely, the physical reality, stability, and macroscopic controllability of extra dimensions. Consequently, while the paper draws on mainstream theoretical physics concepts, the speculative chain linking them lacks empirical support and offers no viable engineering pathway toward a functioning propulsion system.",
