  "id": "release-06-file-045-dow-uap-d141-aawsap-dird-metamaterials-for-aerospace-applications-april-2010",
  "slug": "release-06-file-045-dow-uap-d141-aawsap-dird-metamaterials-for-aerospace-applications-april-2010",
  "title": "DOW-UAP-D141, AAWSAP DIRD, Metamaterials for Aerospace Applications, April 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-04-06",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
