  "id": "release-06-file-046-dow-uap-d142-aawsap-dird-concepts-for-extracting-energy-from-the-quantum-vacuum-april-2010",
  "slug": "release-06-file-046-dow-uap-d142-aawsap-dird-concepts-for-extracting-energy-from-the-quantum-vacuum-april-2010",
  "title": "DOW-UAP-D142, AAWSAP DIRD, Concepts for Extracting Energy from the Quantum Vacuum, April 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-04-06",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
  "location": {
    "name": "Las Vegas, Nevada",
    "region": "North America",
    "lat": 36.17,
    "lng": -115.14
  },
  "classification": "DECLASSIFIED",
  "summary": "This document is a Defense Intelligence Reference Document (DIRD), a technical reference format used by the Defense Intelligence Agency (DIA) to capture baseline knowledge on a specific topic for later analytic use. DIRDs are best understood as reference and synthesis products rather than as original research. It is one of 38 DIRDs produced under the Advanced Aerospace Weapon System Applications Program (AAWSAP) between 2009 and 2011. Because AAWSAP’s scope permitted a broad range of supporting topics, not every DIRD in the series directly concerns aerospace systems or future threat assessment. The following summary reflects the DIRD’s scope and framing at the time of writing and should not be read as implying current validation of the concepts discussed. This DIRD examines whether useful energy might be extracted from the quantum vacuum, the ground state with the lowest possible energy of quantum fields. This treatment considers applications for space power or “propellantless” propulsion by reviewing a range of concepts involving zero-point fluctuations, Casimir effects, squeezed vacuum states, Dirac-vacuum decay, and possible vacuum phase changes in quantum chromodynamics. The report argues that established physical models contain real vacuum-related phenomena, and that certain mechanisms can be modeled as energy-releasing phase changes under specific boundary conditions or intense external fields. However, it acknowledges that no practical method for continuous or useful energy extraction has been demonstrated experimentally and that standard quantum electrodynamics does not support continuous vacuum-energy conversion in the manner proposed. Frameworks based on the concepts described in the DIRD remain theoretically underdeveloped and experimentally unconfirmed at the time of writing.",
