  "slug": "release-06-file-050-dow-uap-d146-aawsap-dird-aneutronic-fusion-propulsion-ii-november-2010",
  "title": "DOW-UAP-D146, AAWSAP DIRD, Aneutronic Fusion Propulsion II, November 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-11-01",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
