  "classification": "DECLASSIFIED",
  "summary": "This document is a Defense Intelligence Reference Document (DIRD), a technical reference format used by the Defense Intelligence Agency (DIA) to capture baseline knowledge on a specific topic for later analytic use. DIRDs are best understood as reference and synthesis products rather than as original research. It is one of 38 DIRDs produced under the Advanced Aerospace Weapon System Applications Program (AAWSAP) between 2009 and 2011. Because AAWSAP’s scope permitted a broad range of supporting topics, not every DIRD in the series directly concerns aerospace systems or future threat assessment. The following summary reflects the DIRD’s scope and framing at the time of writing and should not be read as implying current validation of the concepts discussed. This DIRD revisits aneutronic fusion propulsion in a more systems-oriented manner, arguing that fusion concepts using low-neutron fuels such as proton-boron or helium-3 could become attractive for space propulsion because they reduce shielding burdens and may support direct conversion of charged-particle energy into thrust or onboard power. The report reviews the relevant fusion plasma physics and focuses on several candidate confinement approaches, then connects those concepts to possible applications in near-space, orbital, and interplanetary propulsion. It presents the most plausible nearer-term use as very high-power electric or plasma propulsion for satellites and deep-space missions rather than atmospheric flight or interstellar travel, while emphasizing that major obstacles remain in ignition, sustained confinement, system mass, power handling, fuel storage, launch integration, and end-to-end engineering.",
