  "id": "release-06-file-053-dow-uap-d149-aawsap-dird-mhd-air-breathing-propulsion-and-power-for-aerospace-applications-november-2010",
  "slug": "release-06-file-053-dow-uap-d149-aawsap-dird-mhd-air-breathing-propulsion-and-power-for-aerospace-applications-november-2010",
  "title": "DOW-UAP-D149, AAWSAP DIRD, MHD Air Breathing Propulsion and Power for Aerospace Applications, November 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-11-21",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
  "location": {
    "name": "Las Vegas, Nevada",
    "region": "North America",
    "lat": 36.17,
    "lng": -115.14
  },
  "classification": "DECLASSIFIED",
  "summary": "This document is a Defense Intelligence Reference Document (DIRD), a technical reference format used by the Defense Intelligence Agency (DIA) to capture baseline knowledge on a specific topic for later analytic use. DIRDs are best understood as reference and synthesis products rather than as original research. It is one of 38 DIRDs produced under the Advanced Aerospace Weapon System Applications Program (AAWSAP) between 2009 and 2011. Because AAWSAP’s scope permitted a broad range of supporting topics, not every DIRD in the series directly concerns aerospace systems or future threat assessment. The following summary reflects the DIRD’s scope and framing at the time of writing and should not be read as implying current validation of the concepts discussed. This DIRD surveys magnetohydrodynamic (MHD) and plasma-based concepts for air-breathing propulsion, onboard power generation, and aerodynamic control, arguing that such systems could in principle extend aerospace performance beyond the limits of conventional chemical propulsion and control surfaces. The report reviews concepts including MHD acceleration, flow control, inlet control, onboard power generation, drag reduction, and plasma-generated “virtual” aerodynamic surfaces, while giving particular attention to hypersonic applications such as scramjet power extraction, reentry vehicles, global-strike gliders, and aero-assisted orbital maneuvers. However, it emphasizes major practical constraints, especially extreme power requirements, system weight and complexity, and the difficulty of achieving useful ionization in colder air at lower hypersonic speeds; on that basis, it argues that Ajax-style MHD bypass concepts, in which energy is extracted from the airflow upstream and reintroduced downstream through an electromagnetic system, are not meaningful below about Mach 12, while treating the “virtual cowl” and related reentry applications as more plausible. The document presents plasma and MHD aerospace systems as a technically serious but highly demanding field whose nearer-term promise lies in specialized hypersonic control, power generation, and reentry applications rather than a fully realized air-breathing propulsion system.",
