  "id": "release-06-file-054-dow-uap-d150-aawsap-dird-quantum-computing-and-utilizing-organic-molecules-in-automation-technology-december-2010",
  "slug": "release-06-file-054-dow-uap-d150-aawsap-dird-quantum-computing-and-utilizing-organic-molecules-in-automation-technology-december-2010",
  "title": "DOW-UAP-D150, AAWSAP DIRD, Quantum Computing and Utilizing Organic Molecules in Automation Technology, December 2010",
  "agency": "DOW",
  "category": "archival",
  "date": "2010-12-10",
  "year": 2010,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
