  "id": "release-06-file-056-dow-uap-d152-aawsap-dird-negative-mass-propulsion-january-2011",
  "slug": "release-06-file-056-dow-uap-d152-aawsap-dird-negative-mass-propulsion-january-2011",
  "title": "DOW-UAP-D152, AAWSAP DIRD, Negative Mass Propulsion, January 2011",
  "agency": "DOW",
  "category": "archival",
  "date": "2011-01-03",
  "year": 2011,
  "dateReleased": "2026-09-18",
  "releaseLabel": "Release 06",
  "sourceUrl": "https://war.gov/UFO",
  "location": {
    "name": "Las Vegas, Nevada",
    "region": "North America",
    "lat": 36.17,
    "lng": -115.14
  },
  "classification": "DECLASSIFIED",
  "summary": "This document is a Defense Intelligence Reference Document (DIRD), a technical reference format used by the Defense Intelligence Agency (DIA) to capture baseline knowledge on a specific topic for later analytic use. DIRDs are best understood as reference and synthesis products rather than as original research. It is one of 38 DIRDs produced under the Advanced Aerospace Weapon System Applications Program (AAWSAP) between 2009 and 2011. Because AAWSAP’s scope permitted a broad range of supporting topics, not every DIRD in the series directly concerns aerospace systems or future threat assessment. The following summary reflects the DIRD’s scope and framing at the time of writing and should not be read as implying current validation of the concepts discussed. This DIRD examines whether negative mass could exist in a physically meaningful way and whether it could someday reduce the energy cost of spaceflight. The report reviews the unusual dynamics that would follow if positive and negative mass could interact, including self-accelerating mass pairs and matter with very low or nearly zero effective inertia, and treats such ideas as at least formally compatible with certain extensions of gravitational theory. It then considers two broad paths toward practical use: creating or separating negative mass through extreme fields or particle energies, and locating naturally separated negative matter in deep gravitational wells such as galactic centers or possibly the Moon. However, the document also concludes that the first path is effectively beyond technical reach and treats the second as highly uncertain, resting on a long chain of unverified assumptions about the existence, separability, and macroscopic behavior of negative mass. Overall, this DIRD is a far-reaching theoretical exploration of an exotic propulsion concept whose practical application depends on premises that remain unestablished in consensus physics.",
