  "id": "release-06-file-058-dow-uap-pr130-unresolved-uap-report-iraq-2022",
  "slug": "release-06-file-058-dow-uap-pr130-unresolved-uap-report-iraq-2022",
  "title": "DOW-UAP-PR130, Unresolved UAP Report, Iraq, 2022",
  "agency": "DOW",
  "category": "mission-report",
