  "classification": "DECLASSIFIED",
  "summary": "The United States Central Command submitted a report of an unidentified anomalous phenomenon to the All-domain Anomaly Resolution Office (AARO) consisting of 1 minute of video footage from an infrared sensor aboard a U.S. military platform in 2025. An accompanying mission report, DOW-UAP-D108, described the UAP as “six small spherical objects grouped together, and characterized their behavior as “seem[ingly] agile,” and “frequently changing direction.” The reporter estimated the speed of the UAP to have been 480 miles per hour. Video Description: 00:00-00:04: No content. 00:05-00:10: Several areas of contrast transit the sensor field-of-view, entering from the top of the frame and exiting from the bottom. 00:11-00:47: The sensor pans to track the areas of contrast, keeping them generally within the center of the frame. 00:48-1:00: The sensor changes its level of magnification. No content. This video description is provided for informational purposes only. Readers should not interpret any part of this description as reflecting an analytical judgment, investigative conclusion, or factual determination regarding the described event’s validity, nature, or significance.",
