  "summary": "The United States Central Command submitted a report of an unidentified anomalous phenomenon to the All-domain Anomaly Resolution Office (AARO) consisting of 1 minute and 47 seconds of video footage from an electro-optical and infrared sensor aboard a U.S. military platform in 2022. An accompanying mission report, DOW-UAP-D109, described the UAP as “traveling at various speeds between 80-180 miles per hour.” Video Description: 00:00-00:05: No content. 00:06-00:08: An area of contrast transits the sensor field-of-view, entering from the top of the frame and exiting from the bottom. 00:09-00:15: No content. 00:16-00:26: The sensor pans to track the area of contrast, keeping it generally centered within the frame. 00:27-00:31: The sensor switches to electro-optical mode, and the object moves out of the sensor field-of-view from the left edge of the frame. 00:32-00:45: The sensor switches to infrared mode and pans to track the area of contrast, keeping it generally within the center of the frame. 00:46-01:10: The sensor switches to electro-optical mode and pans to track the area of contrast. 01:11-01:12: No content. 01:13-01:42: The sensor switches to infrared mode and pans to track the area of contrast. 01:43-01:47: The sensor switches to electro-optical mode and pans to track the area of contrast. This video description is provided for informational purposes only. Readers should not interpret any part of this description as reflecting an analytical judgment, investigative conclusion, or factual determination regarding the described event’s validity, nature, or significance.",
