  "classification": "DECLASSIFIED",
  "summary": "The United States Central Command submitted a report of an unidentified anomalous phenomenon to the All-domain Anomaly Resolution Office (AARO) consisting of 2 minutes and 36 seconds of video footage from an electro-optical (right) and infrared (left) sensor aboard a U.S. military platform in 2022. An accompanying mission report, DOW-UAP-D109, described the UAP as “traveling at various speeds between 80-180 miles per hour.” Video Description: 00:00-00:12: An area of contract enters the sensor field-of-view from the lower right of the frame. The sensor pans to track the area of contrast, keeping it generally within the center of the frame. 00:13-00:14: The sensor switches modes to display an infrared (left) and electro-optical (right) feed. 00:15-00:18: The object enters the frame from the lower right, transiting the sensor field-of-view and exiting from the upper left. 00:19-00:20: The sensor switches to infrared mode, panning to track an area of contrast. 00:21-00:27: The sensor switches modes to display an infrared (left) and electro-optical (right) feed. 00:28-00:52: The sensor switches to infrared mode, panning to track an area of contrast. 00:52-00:57: A second area of contrast briefly enters the sensor field-of-view. 00:58-01:16: The sensor pans to track an area of contrast. 01:17-01:21: The sensor switches modes to display an infrared (left) and electro-optical (right) feed. The sensor pans to track the object. The object leaves the sensor field-of-view from the left edge of the frame. 01:22-01:27: No content. 01:28-01:31: The sensor switches to infrared mode. No content. 01:32-02:36: The area of contrast enters the sensor field-of-view from the lower left of the frame. The sensor pans to track the area of contrast, intermittently losing contact with it. This video description is provided for informational purposes only. Readers should not interpret any part of this description as reflecting an analytical judgment, investigative conclusion, or factual determination regarding the described event’s validity, nature, or significance.",
